import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  describe("case normalization (REQ-002)", () => {
    test("converts uppercase to lowercase", () => {
      expect(slugify("Hello")).toBe("hello");
    });

    test("converts mixed case to lowercase", () => {
      expect(slugify("MixedCase123")).toBe("mixedcase123");
    });

    test("leaves lowercase unchanged", () => {
      expect(slugify("already-lowercase")).toBe("already-lowercase");
    });
  });

  describe("whitespace replacement (REQ-003)", () => {
    test("replaces single space with hyphen", () => {
      expect(slugify("Foo Bar")).toBe("foo-bar");
    });

    test("replaces multiple spaces with hyphens", () => {
      expect(slugify("one two  three")).toBe("one-two-three");
    });

    test("replaces underscores with hyphens", () => {
      expect(slugify("Foo__Bar")).toBe("foo-bar");
    });

    test("handles leading spaces", () => {
      expect(slugify("  Leading Space")).toBe("leading-space");
    });

    test("handles trailing spaces", () => {
      expect(slugify("Trailing Space  ")).toBe("trailing-space");
    });
  });

  describe("character filtering (REQ-004)", () => {
    test("removes punctuation", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("retains letters, numbers, and hyphens", () => {
      expect(slugify("abc-123-xyz")).toBe("abc-123-xyz");
    });

    test("removes special characters", () => {
      expect(slugify("test@#$%test")).toBe("testtest");
    });

    test("removes non-ASCII characters", () => {
      expect(slugify("café")).toBe("caf");
    });
  });

  describe("hyphen collapsing (REQ-005)", () => {
    test("collapses double hyphens", () => {
      expect(slugify("a--b")).toBe("a-b");
    });

    test("collapses triple hyphens", () => {
      expect(slugify("a---b")).toBe("a-b");
    });

    test("collapses many consecutive hyphens", () => {
      expect(slugify("a-----b")).toBe("a-b");
    });
  });

  describe("hyphen trimming (REQ-006)", () => {
    test("trims leading hyphen", () => {
      expect(slugify("-hello")).toBe("hello");
    });

    test("trims trailing hyphen", () => {
      expect(slugify("hello-")).toBe("hello");
    });

    test("trims both leading and trailing hyphens", () => {
      expect(slugify("-hyphen-")).toBe("hyphen");
    });

    test("trims multiple leading and trailing hyphens", () => {
      expect(slugify("---hello---")).toBe("hello");
    });
  });

  describe("empty input handling (REQ-007)", () => {
    test("handles empty string", () => {
      expect(slugify("")).toBe("");
    });

    test("handles string with only special characters", () => {
      expect(slugify("!!!")).toBe("");
    });

    test("handles string with only spaces", () => {
      expect(slugify("   ")).toBe("");
    });

    test("handles string with only underscores", () => {
      expect(slugify("___")).toBe("");
    });

    test("handles string with only hyphens", () => {
      expect(slugify("---")).toBe("");
    });
  });

  describe("transformation order (BR-001)", () => {
    test("applies transformations in correct order", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("spaces removed before hyphen collapse", () => {
      expect(slugify("a  b")).toBe("a-b");
    });

    test("punctuation removed creates hyphens to collapse", () => {
      expect(slugify("a,,,,b")).toBe("ab");
    });

    test("complex multi-step transformation", () => {
      expect(slugify("  Hello,   World!!!  ")).toBe("hello-world");
    });
  });

  describe("user story examples", () => {
    test("STORY-001: article title to URL slug", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("STORY-002: normalize file names", () => {
      expect(slugify("Foo__Bar")).toBe("foo-bar");
    });

    test("STORY-003: clean up multiple separators", () => {
      expect(slugify("a---b")).toBe("a-b");
    });

    test("STORY-004: edge case - empty string", () => {
      expect(slugify("")).toBe("");
    });

    test("STORY-004: edge case - all special characters", () => {
      expect(slugify("!!!")).toBe("");
    });

    test("STORY-004: edge case - only whitespace", () => {
      expect(slugify("   ")).toBe("");
    });
  });

  describe("requirements.md test cases", () => {
    test("basic punctuation removal", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("underscore replacement", () => {
      expect(slugify("Foo__Bar")).toBe("foo-bar");
    });

    test("hyphen collapsing", () => {
      expect(slugify("a---b")).toBe("a-b");
    });

    test("leading space handling", () => {
      expect(slugify("  Leading Space")).toBe("leading-space");
    });

    test("trailing space handling", () => {
      expect(slugify("Trailing Space  ")).toBe("trailing-space");
    });

    test("case normalization with numbers", () => {
      expect(slugify("MixedCase123")).toBe("mixedcase123");
    });

    test("all special characters", () => {
      expect(slugify("!!!")).toBe("");
    });

    test("empty string", () => {
      expect(slugify("")).toBe("");
    });

    test("multiple spaces", () => {
      expect(slugify("one two  three")).toBe("one-two-three");
    });

    test("leading/trailing hyphen trim", () => {
      expect(slugify("-hyphen-")).toBe("hyphen");
    });

    test("non-ASCII characters", () => {
      expect(slugify("café")).toBe("caf");
    });
  });

  describe("additional edge cases", () => {
    test("numbers only", () => {
      expect(slugify("12345")).toBe("12345");
    });

    test("single character", () => {
      expect(slugify("a")).toBe("a");
    });

    test("already perfect slug", () => {
      expect(slugify("already-perfect-slug")).toBe("already-perfect-slug");
    });

    test("mixed separators and special chars", () => {
      expect(slugify("foo_bar-baz qux")).toBe("foo-bar-baz-qux");
    });
  });
});

