input.new_string:
/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Transform arbitrary text into URL-safe, filesystem-safe slug strings.
 * Applies 5-step transformation: lowercase -> replace separators -> filter -> collapse -> trim.
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\s_]/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '');
}

